const el=id=>document.getElementById(id), escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let current=0;
const studyKey='ri-study-v1';
function readStudy(){try{const v=JSON.parse(localStorage.getItem(studyKey)||'{}');return{current:Number.isInteger(v.current)&&v.current>=0&&v.current<stages.length?v.current:0,completed:Array.isArray(v.completed)?v.completed.filter(n=>Number.isInteger(n)&&n>=0&&n<stages.length):[]};}catch{return{current:0,completed:[]};}}
let studyState=readStudy();
function persistStudy(){try{localStorage.setItem(studyKey,JSON.stringify(studyState));}catch{}}
function refreshStudyStatus(){const box=el('studyResume');if(!box)return;const count=studyState.completed.length;box.hidden=count===0&&studyState.current===0;el('studyProgressText').textContent=count+' de '+stages.length+' estaciones revisadas \u00b7 \u00faltima visita: '+stages[studyState.current][0];el('resumeStudy').dataset.openStep=String(studyState.current);el('resumeStudy').textContent='Retomar estaci\u00f3n '+String(studyState.current+1).padStart(2,'0');}
function stage(n){current=(n+stages.length)%stages.length;studyState.current=current;persistStudy();let a=stages[current],g=stationGuide[current];el('stepCount').textContent=String(current+1).padStart(2,'0');el('stepRail').innerHTML=stages.map((s,i)=>'<button type="button" class="'+(i===current?'active':'')+'" data-step="'+i+'"><span>'+String(i+1).padStart(2,'0')+'</span>'+escape(s[0])+'</button>').join('');el('stepDetail').innerHTML='<div class="eyebrow">'+escape(a[1])+' / ESTACIÓN '+String(current+1).padStart(2,'0')+'</div><h3>'+escape(a[2])+'</h3><p class="summary">'+escape(a[3])+'</p><div class="facts"><div class="fact"><small>Quién actúa</small><strong>'+escape(a[4])+'</strong></div><div class="fact"><small>Plazo</small><strong>'+escape(a[5])+'</strong></div><div class="fact"><small>Fundamento</small><strong>'+escape(a[6])+'</strong></div></div><div class="station-next"><div><small>Documento o resultado</small><p>'+escape(g[0])+'</p></div><div><small>Qué viene después</small><p>'+escape(g[1])+'</p></div></div><div class="example"><strong>Aplicación a Arcadia</strong>'+escape(a[7])+'</div><div class="nuance"><strong>No confundas</strong>'+escape(a[8])+'</div>';const studied=studyState.completed.includes(current);el('stepDetail').insertAdjacentHTML('beforeend','<div class="study-mark"><label><input id="stageStudied" type="checkbox" '+(studied?'checked':'')+'><span>Marcar esta estaci\u00f3n como estudiada</span></label><small>El avance se guarda solo en este dispositivo.</small></div>');el('stageStudied').addEventListener('change',e=>{studyState.completed=e.target.checked?[...new Set([...studyState.completed,current])]:studyState.completed.filter(n=>n!==current);persistStudy();refreshStudyStatus();});refreshStudyStatus();el('stepProgress').innerHTML=stages.map((_,i)=>'<i class="'+(i<=current?'active':'')+'"></i>').join('');document.querySelectorAll('[data-step]').forEach(b=>b.addEventListener('click',()=>stage(Number(b.dataset.step))));}
el('resumeStudy').addEventListener('click',e=>{e.preventDefault();stage(Number(e.currentTarget.dataset.openStep)||0);});el('resetStudy').addEventListener('click',()=>{studyState={current:0,completed:[]};persistStudy();stage(0);});
el('prevStep').addEventListener('click',()=>stage(current-1));el('nextStep').addEventListener('click',()=>stage(current+1));stage(studyState.current);
el('contrasts').innerHTML=contrasts.map(x=>'<article><h4>'+escape(x[0])+'</h4><p>'+escape(x[1])+'</p></article>').join('');
el('deadlineList').innerHTML=deadlines.map(x=>'<article><header>'+escape(x[0])+'<span>'+x[1]+' '+escape(x[2])+'</span></header><p><strong>Activa:</strong> '+escape(x[3])+'</p><p>'+escape(x[4])+'</p></article>').join('');
el('clockRule').innerHTML=deadlines.map((x,i)=>'<option value="'+i+'">'+escape(x[0])+'</option>').join('');
function addMonths(d,n){let x=new Date(d.getTime()),day=x.getUTCDate();x.setUTCDate(1);x.setUTCMonth(x.getUTCMonth()+n);let m=x.getUTCMonth();x.setUTCMonth(m+1);x.setUTCDate(0);let last=x.getUTCDate();x.setUTCDate(Math.min(day,last));return x;}
function calc(){let x=deadlines[Number(el('clockRule').value)||0],v=el('clockStart').value;if(!/^\d{4}-\d{2}-\d{2}$/.test(v)){el('clockDate').textContent='Selecciona una fecha';return;}let d=new Date(v+'T12:00:00Z');if(!Number.isFinite(d.getTime()))return;let out=x[2]==='meses'?addMonths(d,x[1]):new Date(d.getTime()+x[1]*86400000);el('clockDate').textContent=new Intl.DateTimeFormat('es-ES',{dateStyle:'long',timeZone:'UTC'}).format(out);el('clockTitle').textContent=x[0];el('clockExplanation').textContent='Acto inicial: '+x[3]+'. '+x[5];el('clockAuthority').textContent=x[4]+' · Fecha ORIENTATIVA, no vencimiento jurídico certificado.';}
el('clockGo').addEventListener('click',calc);el('clockRule').addEventListener('change',calc);calc();
const caseStations=[4,0,2,5,7,8,9,11];let caseIndex=0;function viewCase(n){caseIndex=n;let a=caseFacts[n];el('caseList').innerHTML=caseFacts.map((x,i)=>'<button type="button" data-case="'+i+'" class="'+(i===n?'active':'')+'"><span>'+escape(x[0])+'</span><strong>'+escape(x[1])+'</strong></button>').join('');el('caseDetail').innerHTML='<div class="eyebrow">EXPEDIENTE / '+escape(a[0])+'</div><h3>'+escape(a[1])+'</h3><p>'+escape(a[2])+'</p><div class="question"><strong>Pregunta para comprender</strong><p>'+escape(a[3])+'</p></div>';el('caseDetail').insertAdjacentHTML('beforeend','<a class="case-stage-link" href="#recorrido" data-open-step="'+caseStations[n]+'">Repasar estaci\u00f3n relacionada</a>');el('caseDetail').querySelector('[data-open-step]').addEventListener('click',e=>stage(Number(e.currentTarget.dataset.openStep)));document.querySelectorAll('[data-case]').forEach(b=>b.addEventListener('click',()=>viewCase(Number(b.dataset.case))));}viewCase(0);
