let qi=0,score=0,answered=false;function quiz(){answered=false;let q=questions[qi];el('quizIndex').textContent='PREGUNTA '+(qi+1)+' / '+questions.length;el('quizScore').textContent=score+' respuestas correctas';el('quizBar').style.width=(100*qi/questions.length)+'%';el('quizQuestion').textContent=q[0];el('quizOptions').innerHTML=q[1].map((a,i)=>'<button type="button" data-choice="'+i+'">'+escape(a)+'</button>').join('');el('quizFeedback').textContent='Selecciona una opción. La explicación aparecerá aquí.';el('quizNext').disabled=true;el('quizNext').textContent=qi===questions.length-1?'Repetir ejercicio ↺':'Siguiente pregunta →';document.querySelectorAll('[data-choice]').forEach(b=>b.addEventListener('click',()=>{if(answered)return;answered=true;let pick=Number(b.dataset.choice);if(pick===q[2])score++;document.querySelectorAll('[data-choice]').forEach(z=>{z.disabled=true;let k=Number(z.dataset.choice);z.classList.add(k===q[2]?'correct':k===pick?'incorrect':'neutral')});el('quizFeedback').innerHTML='<span>'+escape((pick===q[2]?'Correcto. ':'No exactamente. ')+q[3])+'</span> <a href="#recorrido" data-open-step="'+questionStages[qi]+'">Repasar: '+escape(stages[questionStages[qi]][0])+' \u2197</a>';el('quizFeedback').querySelector('[data-open-step]').addEventListener('click',e=>stage(Number(e.currentTarget.dataset.openStep)));el('quizScore').textContent=score+' respuestas correctas';el('quizNext').disabled=false;}));}
el('quizNext').addEventListener('click',()=>{if(qi===questions.length-1){qi=0;score=0;}else qi++;quiz();});quiz();
