const atlasSearchClear=el('atlasSearchClear');atlasSearch.addEventListener('input',()=>{atlasSearchClear.hidden=!atlasSearch.value.trim();renderSearch();});el('atlasSearchGo').addEventListener('click',()=>{renderSearch();atlasSearch.focus();});atlasSearch.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();renderSearch();searchResults.querySelector('a')?.focus();}if(e.key==='Escape')searchResults.hidden=true;});atlasSearchClear.addEventListener('click',()=>{atlasSearch.value='';atlasSearchClear.hidden=true;searchResults.hidden=true;searchResults.innerHTML='';atlasSearch.focus();});document.querySelectorAll('[data-search-example]').forEach(b=>b.addEventListener('click',()=>{atlasSearch.value=b.dataset.searchExample;atlasSearchClear.hidden=false;renderSearch();atlasSearch.focus();}));
