document.addEventListener('click',e=>{const trigger=e.target.closest('[data-glossary-open]');if(trigger){e.preventDefault();openGlossaryPopover(trigger.dataset.glossaryOpen,trigger);return;}const cardLink=e.target.closest('[data-glossary-card]');if(cardLink){e.preventDefault();const item=glossaryById.get(cardLink.dataset.glossaryCard);closeGlossaryPopover();if(item){glossarySearch.value=item.label;activeGlossaryCategory='Todas';renderGlossaryFilters();renderGlossary();location.hash='diccionario';requestAnimationFrame(()=>{const card=el('term-'+item.id);card?.scrollIntoView({behavior:'smooth',block:'center'});card?.classList.add('glossary-highlight');setTimeout(()=>card?.classList.remove('glossary-highlight'),1500);});}return;}if(glossaryPopover&&!glossaryPopover.hidden&&!e.target.closest('#glossaryPopover'))closeGlossaryPopover();});
